INSERT INTO stage_events (qid, title, summary, start_year, start_month, start_day, end_year, end_month, end_day, precision, display_date, importance, url) VALUES
  ('Q5558443', 'Independence of Panama from Spain', 'Independence of Panama from Spain was accomplished through a bloodless revolt between 10 November 1821 and 28 November 1821. Seizing the opportunity, when the Spanish governor left Panama to march on rebellious Ecuadorians, José de Fábrega led a push for independence.', 1821, 11, 10, 1821, 11, 28, 'day', '10 November 1821 – 28 November 1821', 41, 'https://en.wikipedia.org/wiki/Independence_of_Panama_from_Spain'),
  ('Q5656901', 'Independence Act of Panama', 'The Declaration of Independence of Panama (Acta de Independencia de Panamá) is the document through which Panama declared its independence from the Spanish Empire on November 28, 1821. It was proclaimed in the Cathedral Plaza of Panama City after a council of leaders had met and drafted twelve points calling for severing Panama''s relationship with the Spanish Crown and joining with the newly formed Republic of Gran Colombia.', 1821, 11, 28, NULL, NULL, NULL, 'day', '28 November 1821', 37, 'https://en.wikipedia.org/wiki/Independence_Act_of_Panama'),
  ('Q16639131', '1882 Panama earthquake', 'The 1882 Panama earthquake occurred on September 7 at around 03:50 (UTC-5). The earthquake measured a magnitude between 7.9 and 8.3 on the surface-wave magnitude scale, making it the largest earthquake recorded in Panamanian history.', 1882, 9, 7, NULL, NULL, NULL, 'day', '7 September 1882', 34, 'https://en.wikipedia.org/wiki/1882_Panama_earthquake'),
  ('Q676676', 'Hay–Bunau-Varilla Treaty', 'The Hay–Bunau-Varilla Treaty (Spanish: Tratado Hay-Bunau Varilla) was a treaty signed on November 18, 1903, by the United States and Panama, which established the Panama Canal Zone and the subsequent construction of the Panama Canal. It was named after its two primary negotiators, Philippe-Jean Bunau-Varilla, the French diplomatic representative of Panama, and United States secretary of state John Hay.', 1903, 11, 18, NULL, NULL, NULL, 'day', '18 November 1903', 57, 'https://en.wikipedia.org/wiki/Hay%E2%80%93Bunau-Varilla_Treaty'),
  ('Q3089201', 'separation of Panama from Colombia', 'The secession of Panama from Colombia was formalized on 3 November 1903, with the establishment of the Republic of Panama and the abolition of the Colombia–Costa Rica border. From the independence of Panama from Spain in 1821, Panama had simultaneously joined itself to the confederation of Gran Colombia through the Independence Act of Panama.', 1903, 11, 3, NULL, NULL, NULL, 'day', '3 November 1903', 53, 'https://en.wikipedia.org/wiki/Secession_of_Panama_from_Colombia'),
  ('Q7795915', 'Thomson–Urrutia Treaty', 'The Thomson–Urrutia Treaty was ratified on April 20, 1921, between the United States and Colombia. Based on the terms of the agreement, the U.S. paid Colombia 25 million dollars in return for Colombia''s recognition of Panama''s independence.', 1914, 4, 6, NULL, NULL, NULL, 'day', '6 April 1914', 37, 'https://en.wikipedia.org/wiki/Thomson%E2%80%93Urrutia_Treaty'),
  ('Q114766453', 'Cuban invasion of Panama', 'The Cuban invasion of Panama was a military operation carried out in April 1959 in which Cuban troops, along with some Panamanian guerrillas, sought to initiate a revolution in Panama modeled after the Cuban example. The mission was led by Panamanian Enrique Morales in support of a coup attempt by Roberto Arias.', 1959, 4, 3, 1959, 5, 1, 'day', '3 April 1959 – 1 May 1959', 30, 'https://en.wikipedia.org/wiki/Cuban_invasion_of_Panama'),
  ('Q5882533', '1968 Panamanian coup d''état', 'The 1968 Panamanian coup d''état was the military coup that took place in the Republic of Panama on October 11, 1968, when the National Guard, led by Major Boris Martínez, Lieutenant Colonel Jose Humberto Ramos, Rubén Darío Paredes and other military officers overthrew President Arnulfo Arias, who was elected in the May 12 general election and assumed office on October 1.', 1968, 10, 11, NULL, NULL, NULL, 'day', '11 October 1968', 34, 'https://en.wikipedia.org/wiki/1968_Panamanian_coup_d''%C3%A9tat'),
  ('Q459282', 'United States invasion of Panama', 'The United States invasion of Panama began in mid-December 1989 during the presidency of George H. W. Bush. The purpose of the invasion was to depose the de facto ruler of Panama, General Manuel Noriega, who was wanted by U.S. authorities for racketeering and drug trafficking.', 1989, 12, 20, 1990, 1, 31, 'day', '20 December 1989 – 31 January 1990', 70, 'https://en.wikipedia.org/wiki/United_States_invasion_of_Panama'),
  ('Q7096729', 'Operation Acid Gambit', 'Operation Acid Gambit took place as an opening action of the United States invasion of Panama, on 20 December 1989. It was a U.S. Delta Force operation that retrieved Kurt Muse, a rumored asset of the Central Intelligence Agency, operating in Panama who had been arrested for leading a plot with other Panamanians to overthrow the government of Panama, from the Cárcel Modelo, a notorious prison in Panama City.', 1989, 12, 20, NULL, NULL, NULL, 'day', '20 December 1989', 34, 'https://en.wikipedia.org/wiki/Operation_Acid_Gambit'),
  ('Q5168156', 'Copa Airlines Flight 201', 'Copa Airlines Flight 201 was a regularly scheduled passenger flight from Tocumen International Airport in Panama City, Panama, to Alfonso Bonilla Aragón International Airport in Cali, Colombia. On 6 June 1992, the Boeing 737-200 operating the route rolled, entered a steep dive, disintegrated in mid-air, and crashed into the jungle of the Darién Gap 29 minutes after takeoff, killing all 47 people on board.', 1992, 6, 6, NULL, NULL, NULL, 'day', '6 June 1992', 50, 'https://en.wikipedia.org/wiki/Copa_Airlines_Flight_201'),
  ('Q4601757', '2003 Puerto Armuelles earthquake', 'The 2003 Puerto Armuelles earthquake occurred on December 25 at 02:11 local time (07:11 UTC). The epicenter was located in Panama, at about 7 km east of Puerto Armuelles, near the Panama-Costa Rica border.', 2003, 12, 25, NULL, NULL, NULL, 'day', '25 December 2003', 34, 'https://en.wikipedia.org/wiki/2003_Puerto_Armuelles_earthquake'),
  ('Q81068910', 'COVID-19 pandemic', 'The global COVID-19 pandemic (also known as the coronavirus pandemic), caused by severe acute respiratory syndrome coronavirus 2 (SARS-CoV-2), began with an outbreak in Wuhan, China, in December 2019. It spread to other parts of Asia and then worldwide in early 2020.', 2019, 12, 1, NULL, NULL, NULL, 'day', '1 December 2019', 100, 'https://en.wikipedia.org/wiki/COVID-19_pandemic'),
  ('Q141681530', '2026 Panama earthquake', 'On 9 October 2026, at 12:56:06 EST (17:56:06 UTC), a Mw 7.7 earthquake struck the Azuero Peninsula within Panama. The earthquake caused significant damage across several parts of the country, killed at least three people and injured at least 27 others.', 2026, 10, 9, NULL, NULL, NULL, 'day', '9 October 2026', 43, 'https://en.wikipedia.org/wiki/2026_Panama_earthquake');
